                UIHelper.hideKeyboard(getContext(), getDialog().getCurrentFocus());

            btnSave.setEnabled(true);
        }
    }

    @Override
    public void onItemClick(AdapterView<?> parent, View view, int position, long id) {
        value = entryValues.get(position);
        updateLayout();
    }

