// Sync password visibility between primary and confirm fields.
// We use reflection to hook into Material Design's internal password toggle
// because the library's toggle mechanism doesn't trigger TextWatcher events
// (it toggles a text filter, not the underlying text buffer).
try {
    java.lang.reflect.Field toggleField = TextInputLayout.class.getDeclaredField("mPasswordToggleView");
    toggleField.setAccessible(true);
    android.widget.CompoundButton toggleButton = (android.widget.CompoundButton) toggleField.get(passwordLayout);
    if (toggleButton != null) {
        toggleButton.setOnCheckedChangeListener(
            new android.widget.CompoundButton.OnCheckedChangeListener() {
                @Override
                public void onCheckedChanged(android.widget.CompoundButton buttonView, boolean isChecked) {
                    if (isChecked) {
                        passwordConfirm.setTransformationMethod(null);
                    } else {
                        passwordConfirm.setTransformationMethod(new PasswordTransformationMethod());
                    }
                }
            });
    }
} catch (Exception e) {
    // Reflection failed; the password visibility sync is not available.
}

